def _g_round_nonce():
    _v = 0
    _v = _v * 3
    _v = _v + 10
    _v = _v - 8
    _v = _v + 7
    _v = _v * 9
    _v = _v * 6
    _v = _v - 2
    _v = _v * 6
    return _v
